// GPL-2.0: authoritative original quests; acceptance/objective/reward boundaries follow ServUO BaseQuest.
using System.Text.Json;
using Greyhaven.Content;
namespace Greyhaven.Server;
public static class AdventureSimulation {
 public static void Initialize(ContentPackage p,SessionState s){if(s.Adventure.Version==1)return;var a=s.Adventure=new(){Version=1,Enabled=p.Map.Objects.Any(o=>o.Kind=="npc")&&p.AdventureCatalog.Quests.Count>0,NextRestockAt=s.ElapsedSeconds+3600};if(!a.Enabled)return;
  a.Skills=AdventureRules.Skills.Select(d=>new SkillProgress{Id=d.Id,Value=d.Start}).ToList();a.Npcs=p.Map.Objects.Where(o=>o.Kind=="npc").Select(o=>new NpcProgress{Id=o.Id,X=o.X,Y=o.Y,MoveAt=s.ElapsedSeconds+2}).ToList();a.Quests=p.AdventureCatalog.Quests.Where(q=>AdventureRules.Applicable(p,q)).Select(q=>new QuestProgress{Id=q.Id,Counts=q.Objectives.Select(o=>0).ToList()}).ToList();
  if(s.Items.Count<InventoryRules.MaxItems&&!s.Items.Any(i=>i.Id=="adventure.bandages"))Give(p,s,"greyhaven.item.bandage",10,"adventure.bandages");if(!s.MerchantStock.Any(i=>i.Definition=="greyhaven.item.bandage"))s.MerchantStock.Add(new(){Definition="greyhaven.item.bandage",Amount=20});EnsureHeart(p,s);AdventureRules.Validate(p,s);
 }
 public static bool Handles(string type)=>type is "quest-accept" or "quest-abandon" or "quest-claim" or "quest-mark" or "restore-beacon" or "skill-lock" or "stat-lock" or "train" or "meditate" or "bandage" or "resurrect";
 public static MapObject RequireNpc(ContentPackage p,SessionState s,string id){var o=p.Map.Objects.FirstOrDefault(o=>o.Id==id&&o.Kind=="npc")??throw new ContentException("Unknown resident.");var at=AdventureRules.Position(s,o);if(CombatRules.Distance(s.X,s.Y,at.x,at.y)>2)throw new ContentException("Move within two tiles of that resident.");var n=AdventureRules.Npc(s,id);if(n!=null)n.HoldUntil=s.ElapsedSeconds+10;return o;}
 public static (SessionState state,string message) Apply(ContentPackage p,SessionState original,Command c){if(!original.Adventure.Enabled)throw new ContentException("This map has no town adventure cast.");if(original.Paused)throw new ContentException("Campaign paused.");if(original.Combat.Dead&&c.Type is not ("resurrect" or "skill-lock" or "stat-lock"))throw new ContentException("Return as a living wayfarer before continuing this business.");if(c.ExpectedRevision>=0&&c.ExpectedRevision!=original.Revision)throw new ContentException("Your inventory changed. Review the quest again.");var s=JsonSerializer.Deserialize<SessionState>(Wire.Encode(original),ContentPackage.Json)!;var a=s.Adventure;string message;
  if(c.Type=="skill-lock"){if(c.Destination is not ("up" or "down" or "locked"))throw new ContentException("Choose gain, decrease or lock.");AdventureRules.Skill(s,c.ItemId).Lock=c.Destination;message="Skill lock changed.";}
  else if(c.Type=="stat-lock"){if(c.Destination is not ("up" or "down" or "locked"))throw new ContentException("Invalid stat lock.");if(c.ItemId=="str")a.StrengthLock=c.Destination;else if(c.ItemId=="dex")a.DexterityLock=c.Destination;else if(c.ItemId=="int")a.IntelligenceLock=c.Destination;else throw new ContentException("Unknown statistic.");message="Stat lock changed.";}
  else if(c.Type=="train")message=ProgressionSimulation.Train(p,s,c);
  else if(c.Type=="meditate")message=ProgressionSimulation.Meditate(s);
  else if(c.Type=="bandage")message=ProgressionSimulation.Bandage(s);
  else if(c.Type=="resurrect"){var npc=RequireNpc(p,s,c.TargetId);if(!s.Combat.Dead||npc.Role!="healer")throw new ContentException("A healer can restore a fallen spirit.");s.Combat.Dead=false;s.Combat.Health=10;s.Combat.Status=new();s.Combat.GraceUntil=s.ElapsedSeconds+10;message=npc.Name+" restores your life. Your possessions remain at your fallen pack.";}
  else if(c.Type=="restore-beacon"){
   if(!a.Quests.Any(q=>q.Id==AdventureRules.MainQuest&&q.Status is "active" or "ready"))throw new ContentException("Accept Sera's beacon quest first.");var stair=p.Map.Objects.FirstOrDefault(o=>o.Id=="stairs.beacon")??throw new ContentException("This map has no beacon.");if(CombatRules.Distance(s.X,s.Y,stair.X,stair.Y)>2)throw new ContentException("Carry the heart to the stair marker at the Broken Beacon.");if(a.BeaconRestored)throw new ContentException("The beacon is already alight.");var heart=s.Items.FirstOrDefault(i=>i.Id==AdventureRules.Heart&&InventoryRules.Carried(s,i))??throw new ContentException("Carry the Lantern Heart first.");if(!s.Combat.Enemies.Any(e=>e.Id=="encounter.lower.boss"&&e.Health==0))throw new ContentException("The Lantern Keeper still holds the beacon's power.");ProgressionSimulation.Consume(s,heart,1);a.BeaconRestored=true;message="The Lantern Heart settles into the beacon. Its light returns across Greyhaven's reef. Return to Sera.";
  }else{
   var d=p.AdventureCatalog.Quests.FirstOrDefault(q=>q.Id==c.TargetId)??throw new ContentException("Unknown quest.");var q=a.Quests.FirstOrDefault(q=>q.Id==d.Id)??throw new ContentException("That quest does not belong to this map.");
   if(c.Type=="quest-accept"){
    RequireNpc(p,s,d.Giver);if(q.Status!="available")throw new ContentException("This quest has already been accepted or rewarded.");q.Status="active";q.AcceptedAt=s.ElapsedSeconds;q.Counts=d.Objectives.Select(o=>0).ToList();if(d.Id=="quest.harbour"){if(s.Items.Count>=InventoryRules.MaxItems||s.Items.Any(i=>i.Id==AdventureRules.Mail))throw new ContentException("Free an inventory entity slot for Mara's letters.");s.Items.Add(new(){Id=AdventureRules.Mail,Definition="greyhaven.item.sealed-scroll",Label="Mara's Harbour Letters",QuestId=d.Id,X=100,Y=180});}message="Accepted: "+d.Name;
   }else if(c.Type=="quest-abandon"){
    if(q.Status is not ("active" or "ready"))throw new ContentException("There is no active quest to abandon.");q.Status="available";q.Counts=d.Objectives.Select(o=>0).ToList();foreach(var i in s.Items.Where(i=>i.QuestId==d.Id&&i.Id!=AdventureRules.Heart).ToList()){if(i.Id==AdventureRules.Mail)ProgressionSimulation.Consume(s,i,i.Amount);else i.QuestId="";}message="Abandoned: "+d.Name+". You may accept it again.";
   }else if(c.Type=="quest-mark"){
    if(q.Status is not ("active" or "ready"))throw new ContentException("Accept this supply quest before marking items.");var objectives=d.Objectives.Where(o=>o.Kind=="obtain"&&o.Target.StartsWith("greyhaven.item.")).ToList();if(objectives.Count==0)throw new ContentException("This quest has no supplies to mark.");var items=s.Items.Where(i=>InventoryRules.Carried(s,i)&&objectives.Any(o=>o.Target==i.Definition)&&(c.ItemId==""||i.Id==c.ItemId)).ToList();if(items.Count==0)throw new ContentException("Carry the required supplies first.");foreach(var i in items){if(i.Id.StartsWith("quest.item.")||i.QuestId!=""&&i.QuestId!=d.Id)throw new ContentException("This item belongs to another quest.");i.QuestId=c.Destination=="unmark"?"":i.QuestId==d.Id&&c.ItemId!=""?"":d.Id;}message="Quest item marks updated.";
   }else if(c.Type=="quest-claim"){
    RequireNpc(p,s,d.Recipient);Evaluate(p,s);if(q.Status!="ready")throw new ContentException("Complete every objective and carry the required quest items first.");
    foreach(var objective in d.Objectives.Where(o=>o.Kind is "obtain" or "deliver")){if(d.Main&&a.BeaconRestored&&objective.Target==AdventureRules.Heart)continue;int need=objective.Amount;foreach(var i in s.Items.Where(i=>i.QuestId==d.Id&&InventoryRules.Carried(s,i)&&(i.Id==objective.Target||i.Definition==objective.Target)).ToList()){int n=Math.Min(need,i.Amount);ProgressionSimulation.Consume(s,i,n);need-=n;if(need==0)break;}if(need!=0)throw new ContentException("The required quest items are no longer in your possession.");}
    foreach(var item in s.Items.Where(i=>i.QuestId==d.Id))item.QuestId="";foreach(var reward in d.Rewards)Give(p,s,reward.Definition,reward.Amount);a.Fame=Math.Clamp(a.Fame+Math.Max(0,d.Fame-a.Fame/100),0,32000);a.Karma=Math.Clamp(a.Karma+d.Karma-a.Karma/100,-32000,32000);q.Status="claimed";q.CompletedAt=s.ElapsedSeconds;message=d.Completion;
   }else throw new ContentException("Unknown quest action.");
  }
  Evaluate(p,s);InventoryRules.Validate(p,s);AdventureRules.Validate(p,s);InventoryTransactions.Log(s,message);s.Revision++;return(s,message);
 }
 public static void Give(ContentPackage p,SessionState s,string definition,int amount,string? id=null){var d=p.Definitions.Items.First(d=>d.Id==definition);if(d.Stackable&&id==null)foreach(var i in s.Items.Where(i=>i.Definition==definition&&i.QuestId==""&&InventoryRules.Carried(s,i)&&i.Amount<InventoryRules.MaxStack).ToList()){int n=Math.Min(amount,InventoryRules.MaxStack-i.Amount);i.Amount+=n;try{InventoryRules.Validate(p,s);amount-=n;}catch(ContentException){i.Amount-=n;}if(amount==0)return;}
  while(amount>0){if(s.Items.Count>=InventoryRules.MaxItems)throw new ContentException("Free an item entity slot before collecting this reward. Nothing was consumed.");int n=d.Stackable?Math.Min(amount,InventoryRules.MaxStack):1;var i=new WorldItem{Id=id??"reward."+Guid.NewGuid().ToString("N"),Definition=definition,Amount=n,X=95,Y=180};s.Items.Add(i);try{InventoryRules.Validate(p,s);}catch(ContentException){i.Where="ground";i.X=s.X;i.Y=s.Y;i.Z=s.Z;InventoryRules.Validate(p,s);}amount-=n;}
 }
 public static void Talk(ContentPackage p,SessionState s,string id){if(!s.Adventure.Enabled||s.Combat.Dead)return;var npc=p.Map.Objects.FirstOrDefault(o=>o.Id==id&&o.Kind=="npc");if(npc==null)return;if(!s.Adventure.Talked.Contains(id))s.Adventure.Talked.Add(id);var n=AdventureRules.Npc(s,id);if(n!=null)n.HoldUntil=s.ElapsedSeconds+10;Evaluate(p,s);}
 public static void EnsureHeart(ContentPackage p,SessionState s){var a=s.Adventure;if(!a.Enabled||!a.Quests.Any(q=>q.Id==AdventureRules.MainQuest)||a.HeartCreated||a.BeaconRestored||!s.Combat.Enemies.Any(e=>e.Id=="encounter.lower.boss"&&e.Health==0)||s.Items.Count>=InventoryRules.MaxItems)return;var boss=s.Combat.Enemies.First(e=>e.Id=="encounter.lower.boss");if(!s.Items.Any(i=>i.Id==AdventureRules.Heart))s.Items.Add(new(){Id=AdventureRules.Heart,Definition="greyhaven.item.tide-crystal",QuestId=AdventureRules.MainQuest,Label="The Lantern Heart",Where="ground",X=boss.X,Y=boss.Y,Z=boss.Z});a.HeartCreated=true;InventoryTransactions.Log(s,"The Lantern Heart lies beside the fallen Keeper.");}
 public static void Evaluate(ContentPackage p,SessionState s){if(!s.Adventure.Enabled)return;foreach(var q in s.Adventure.Quests.Where(q=>q.Status is "active" or "ready")){var d=p.AdventureCatalog.Quests.First(d=>d.Id==q.Id);for(int n=0;n<d.Objectives.Count;n++){var o=d.Objectives[n];int count=o.Kind switch{
   "talk"=>s.Adventure.Talked.Contains(o.Target)?1:0,"visit"=>s.World.Visited.Contains(o.Target)?1:0,"collect"=>s.Items.Any(i=>i.Id==o.Target&&InventoryRules.Carried(s,i))||s.Adventure.BeaconRestored?1:0,"object"=>WorldAuthoring.Progress(s,o.Target)?.Active==true?1:0,"kill"=>s.Combat.Enemies.Any(e=>e.Id==o.Target&&e.Health==0)?1:0,"restore"=>s.Adventure.BeaconRestored?1:0,"obtain"=>o.Target==AdventureRules.Heart&&s.Adventure.BeaconRestored?1:s.Items.Where(i=>i.QuestId==d.Id&&InventoryRules.Carried(s,i)&&(i.Definition==o.Target||i.Id==o.Target)).Sum(i=>i.Amount),"deliver"=>s.Adventure.Talked.Contains(d.Recipient)&&s.Items.Any(i=>i.Id==o.Target&&InventoryRules.Carried(s,i))?1:0,_=>0};if(o.Kind is not "obtain")count=Math.Max(count,q.Counts[n]);q.Counts[n]=Math.Min(o.Amount,count);}
   bool complete=q.Counts.Where((n,i)=>n<d.Objectives[i].Amount).Any()==false;if(complete&&q.Status!="ready")InventoryTransactions.Log(s,"Objectives complete: "+d.Name+". Collect the reward from "+p.Map.Objects.First(o=>o.Id==d.Recipient).Name+".");q.Status=complete?"ready":"active";
  }}
 public static void Advance(ContentPackage p,SessionState s,double dt){if(s.Paused||!s.Adventure.Enabled)return;EnsureHeart(p,s);ProgressionSimulation.Advance(p,s,dt);if(s.ElapsedSeconds>=s.Adventure.NextRestockAt){foreach(var stock in s.MerchantStock)stock.Amount=Math.Max(20,stock.Amount);s.Adventure.NextRestockAt=s.ElapsedSeconds+3600;InventoryTransactions.Log(s,"Nessa replenishes the shop's supplies.");}TownSimulation.Advance(p,s);Evaluate(p,s);}
}
